    /* знак в шапке — только после того, как большой знак ушёл под плашку (в обеих версиях) */
    [['bbar','bigmark'],['bbar2','bigmark2']].forEach(function(pr){
      var bar_=document.getElementById(pr[0]), bigm=document.getElementById(pr[1]); if(!bar_||!bigm) return;
      var lt=false, chk=function(){ lt=false; var mb=bigm.getBoundingClientRect(), hb=bar_.getBoundingClientRect();
        bar_.classList.toggle('logo-on', mb.height>0 && mb.bottom<=hb.bottom); };
      window.addEventListener('scroll',function(){ if(!lt){ lt=true; requestAnimationFrame(chk); setTimeout(function(){ if(lt) chk(); },120); } },{passive:true});
      window.addEventListener('resize',chk); document.addEventListener('click',function(){ setTimeout(chk,80); }); chk();
    });

